begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create function pg_temp.record_p(n integer,kind text,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('id',('b4000000-0000-4000-8000-'||lpad(n::text,12,'0')),'patient_id','b2000000-0000-4000-8000-000000000001','event_id',('b3000000-0000-4000-8000-'||lpad(n::text,12,'0')),'specialty',kind,'version',v,'operation_key',gen_random_uuid(),'occurred_at',now()-interval '2 hours','payload',jsonb_build_object('objective','Objetivo neutro QA','evolution','not_evaluable','facts','Hechos neutros QA'),'reserved_note','','summary_body','','summary_visibility','none','request_intervention',false,'request_body','','request_due_at','','reason','','confirm_finalize',true,'confirm_publish',false)$$;
create temporary table records_fixture(name text primary key,p jsonb);
grant select,insert,update on records_fixture to authenticated;
insert into auth.users(id,email) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test' from generate_series(1,7)n;
insert into public.admin_users(user_id,role,is_active) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(case when n=7 then 'editor' else 'viewer' end)::public.admin_role,true from generate_series(3,7)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name) select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test','Persona record QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create']||case when n=5 then array['care.medical.create'] else array[]::text[] end from generate_series(3,5)n;
insert into public.care_staff_capabilities(user_id,capabilities) values('b1000000-0000-4000-8000-000000000006',array['care.directory.read','care.patient.read','care.records.read','care.assignments.manage','care.decisions.manage']);
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) select 'b2000000-0000-4000-8000-000000000001',('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' when 5 then 'psychiatry' else 'direction' end,now()-interval '1 day','b1000000-0000-4000-8000-000000000006' from generate_series(3,6)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) values('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000006','direction',now()-interval '1 day','b1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by) select ('b3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión neutra QA '||n,case n when 2 then 'recovery' when 3 then 'psychiatry' else 'individual' end,now()-interval '2 hours',now()-interval '1 hour',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid,'in_person',case when n=5 then 'cancelled' else 'completed' end,now()-interval '30 minutes',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid from generate_series(1,6)n;
insert into public.care_event_participants(event_id,patient_id,attendance) select id,'b2000000-0000-4000-8000-000000000001',case when title like '%6' then 'pending' else 'present' end from public.care_events where id::text like 'b3000000-%';

insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000004','recovery',now()-interval '1 day','b1000000-0000-4000-8000-000000000006');
insert into public.care_event_participants(event_id,patient_id,attendance)values('b3000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000002','absent');
create function pg_temp.rc_payload()returns jsonb language sql as $$select jsonb_build_object('objective','Actividad neutral QA','evolution','not_evaluable','activity_type','group','recovery_participation','full','support','occasional','support_details','Apoyo ocasional observado QA','facts','Tarea neutral y resultado QA','progress','Sin avances observables QA','difficulties','Sin dificultades observables QA','evidence_source','observed','evidence','Observación directa de tarea neutral QA','no_commitment_reason','No se acordó nueva tarea QA')$$;
set local role anon;
select pg_temp.care_denied($$select public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')$$,'Anon no Recovery review RPC');
reset role;set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
insert into records_fixture values('rc',pg_temp.record_p(2,'recovery')||jsonb_build_object('payload','{}'::jsonb));
select public.care_record_write('draft',(select p from records_fixture where name='rc'));
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000002')->'draft'->'payload'='{}'::jsonb,'Incomplete Recovery draft remains private and persists without levels');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(2,'recovery',1))$$,'Finalization requires explicit qualitative fields','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(2,'recovery',1)||jsonb_build_object('payload',pg_temp.rc_payload()||jsonb_build_object('recovery_participation','absent','participation_reason','Ausencia QA','support','none')))$$,'Absence is never no support','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(2,'recovery',1)||jsonb_build_object('payload',pg_temp.rc_payload()||jsonb_build_object('recovery_participation','absent','participation_reason','Ausencia QA','support','not_observable')))$$,'Participation agrees with separate attendance source','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(2,'recovery',1)||jsonb_build_object('payload',pg_temp.rc_payload()-'no_commitment_reason'))$$,'No new commitment requires explicit reason','P0001');
update records_fixture set p=pg_temp.record_p(2,'recovery',1)||jsonb_build_object('author_id','b1000000-0000-4000-8000-000000000006','payload',pg_temp.rc_payload()||jsonb_build_object('no_commitment_reason','','recovery_commitment_id','b5000000-0000-4000-8000-000000000001','commitment_title','Tarea concreta neutral QA','commitment_due_at',(now()-interval '1 hour')::text,'commitment_review_at',(now()+interval '1 day')::text,'commitment_method','Revisar resultado concreto neutral QA','commitment_responsible','patient'))where name='rc';
select public.care_record_write('finalize',(select p from records_fixture where name='rc'));
select public.care_record_write('finalize',(select p from records_fixture where name='rc'));
select pg_temp.care_assert((select count(*)=1 from public.care_commitments where source_record_id='b4000000-0000-4000-8000-000000000002'),'Atomic linked commitment is idempotent, not only text');
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000002')->'record'->>'author_id'='b1000000-0000-4000-8000-000000000004','Author generated by authenticated server, ignores forged author');
select pg_temp.care_assert(public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')->0->>'review_at' is not null,'Real commitment has review date and method');
select pg_temp.care_denied($$select public.care_planning_manage('commitment_complete',jsonb_build_object('id','b5000000-0000-4000-8000-000000000001','version',1,'result','Resultado sin evidencia QA','reason','QA revisión'))$$,'Generic professional completion cannot bypass Recovery evidence','P0001');
select public.care_record_write('finalize',pg_temp.record_p(2,'recovery')||jsonb_build_object('id','b4000000-0000-4000-8000-000000000009','patient_id','b2000000-0000-4000-8000-000000000002','payload',pg_temp.rc_payload()||jsonb_build_object('recovery_participation','absent','participation_reason','Ausencia registrada QA','support','not_observable','progress','Sin avances observables por ausencia QA')));
select pg_temp.care_assert((select count(*)=2 from public.care_session_records where event_id='b3000000-0000-4000-8000-000000000002'),'Group uses one event and individual records');
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000009')->'versions'->0->'payload'->>'support'='not_observable','Absent group participant keeps own no observation, no copied support');
select pg_temp.care_assert((select count(*)=1 from public.care_commitments),'Motivated exception creates no fictitious task');
insert into records_fixture values('review',jsonb_build_object('id','b5000000-0000-4000-8000-000000000001','version',1,'outcome','unverifiable','result','Resultado insuficiente neutral QA','evidence','Declaración sin resultado verificable QA','support','Apoyo no observado neutral QA','difficulties','Información insuficiente neutral QA','reason','Revisión neutral QA'));
select public.care_rc_commitment_review((select p from records_fixture where name='review'));
select pg_temp.care_assert(public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')->0->'reviews'->0->>'outcome'='unverifiable','No verificable stored distinctly from incumplido');
select pg_temp.care_assert((select status='pending' and due_at<now() from public.care_commitments where id='b5000000-0000-4000-8000-000000000001'),'Overdue remains temporal, no automatic breach');
select pg_temp.care_denied($$select public.care_rc_commitment_review((select p from records_fixture where name='review'))$$,'Stale review rejects concurrent overwrite','40001');
select public.care_rc_commitment_review((select p||jsonb_build_object('version',2,'outcome','fulfilled')from records_fixture where name='review'));
select pg_temp.care_assert((select status='completed' and confirmation='professional' from public.care_commitments where id='b5000000-0000-4000-8000-000000000001'),'Professional fulfilled review maps additively to verified completion');
select public.care_rc_commitment_review((select p||jsonb_build_object('version',3,'outcome','unfulfilled','reason','Corrección motivada QA')from records_fixture where name='review'));
select pg_temp.care_assert(jsonb_array_length(public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')->0->'reviews')=3,'Correction preserves original review evidence author date');
select pg_temp.care_assert(public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')->0->'reviews'->0->>'outcome'='unfulfilled','Verified failure is an explicit professional result');
select pg_temp.care_denied($$select * from private.care_recovery_commitment_reviews$$,'Normal authenticated cannot read private review table directly');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_denied($$select public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')$$,'Patient no professional review evidence');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000007',true);
select pg_temp.care_denied($$select public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')$$,'CMS editor no clinical review by role');
reset role;
update public.care_assignments set ends_at=now() where professional_id='b1000000-0000-4000-8000-000000000004';
set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select pg_temp.care_denied($$select public.care_rc_commitments('b2000000-0000-4000-8000-000000000001')$$,'Revocation rejects old Recovery session');
rollback;
